<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ausencias y reposiciones — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033}.wrap{max-width:980px;margin:auto;padding:78px 12px 32px}h1{margin:0 0 4px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.card{background:#fff;border-radius:14px;padding:14px;margin-bottom:12px}.grid{display:grid;gap:10px}.field label{display:block;font-size:11px;font-weight:800;color:#64748b;margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:10px 11px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;font-size:15px}.field textarea{min-height:70px}.btn{border:0;border-radius:9px;padding:10px 12px;font-weight:800;cursor:pointer}.btn-primary{background:#172033;color:#fff}.btn-danger{background:#fff1f2;color:#9f1239}.row{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;padding:11px 0;border-bottom:1px solid #eef2f7}.row:last-child{border:0}.name{font-weight:800}.meta{font-size:12px;color:#64748b;margin-top:3px}.status{font-size:10px;font-weight:900;border-radius:999px;padding:4px 7px;background:#e8eef2}.section{margin-top:18px}.section h2{font-size:18px;margin:0 0 10px}.empty{text-align:center;color:#64748b;padding:20px}.repo{display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid #eef2f7}.repo:last-child{border:0}.count{font-size:18px;font-weight:900}@media(min-width:760px){.wrap{padding-top:35px}.grid{grid-template-columns:1.4fr 1fr 1fr}.field.full{grid-column:1/-1}}</style></head><body><main class="wrap"><h1>Ausencias y reposiciones</h1><div class="sub">Avisos anticipados y saldo disponible</div><section class="card"><div class="grid"><div class="field"><label>Alumno</label><select id="alumno"><option value="">Seleccionar…</option></select></div><div class="field"><label>Desde</label><input id="desde" type="date"></div><div class="field"><label>Hasta</label><input id="hasta" type="date"></div><div class="field full"><label>Motivo</label><textarea id="motivo" placeholder="Ej. viaje, vacaciones, cita médica…"></textarea></div></div><button id="guardar" class="btn btn-primary">Registrar aviso</button></section><section class="section"><h2>Avisos</h2><div id="avisos" class="card"><div class="empty">Cargando…</div></div></section><section class="section"><h2>Reposiciones disponibles</h2><div id="repos" class="card"><div class="empty">Cargando…</div></div></section></main><script>const alumno=document.getElementById('alumno'),desde=document.getElementById('desde'),hasta=document.getElementById('hasta'),avisos=document.getElementById('avisos'),repos=document.getElementById('repos');const hoy=new Date().toISOString().slice(0,10);desde.value=hoy;hasta.value=hoy;async function post(body){const r=await fetch('/api/ausencias-programadas.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}async function alumnos(){const r=await fetch('/api/alumnos.php'),d=await r.json();if(d.ok)(d.alumnos||[]).sort((a,b)=>(a.nombre||'').localeCompare(b.nombre||'','es')).forEach(a=>alumno.insertAdjacentHTML('beforeend',`<option value="${a.id}">${a.nombre}</option>`))}async function cargar(){const r=await fetch('/api/ausencias-programadas.php'),d=await r.json();if(!d.ok){avisos.innerHTML='<div class="empty">Error al cargar.</div>';return}avisos.innerHTML=d.avisos.length?d.avisos.map(x=>`<div class="row"><div><div class="name">${x.nombre}</div><div class="meta">${x.fecha_desde}${x.fecha_hasta!==x.fecha_desde?' → '+x.fecha_hasta:''}${x.motivo?' · '+x.motivo:''}</div></div><div>${x.estado==='ACTIVO'?`<button class="btn btn-danger" data-cancel="${x.id}">Cancelar</button>`:`<span class="status">CANCELADO</span>`}</div></div>`).join(''):'<div class="empty">Sin avisos registrados.</div>';repos.innerHTML=d.reposiciones.length?d.reposiciones.map(x=>`<div class="repo"><span>${x.nombre}</span><span class="count">${x.disponibles}</span></div>`).join(''):'<div class="empty">No hay reposiciones disponibles.</div>'}document.getElementById('guardar').onclick=async()=>{if(!alumno.value)return alert('Selecciona un alumno');try{await post({accion:'CREAR',alumno_id:alumno.value,fecha_desde:desde.value,fecha_hasta:hasta.value,motivo:document.getElementById('motivo').value});document.getElementById('motivo').value='';cargar()}catch(e){alert(e.message)}};avisos.onclick=async e=>{const b=e.target.closest('[data-cancel]');if(!b)return;if(!confirm('¿Cancelar este aviso?'))return;try{await post({accion:'CANCELAR',id:b.dataset.cancel});cargar()}catch(err){alert(err.message)}};alumnos();cargar();</script></body></html>